// Des: Start the app: read args and config, lock, open state, open the browser only if needed
// Flo: args > aa-conf-main.json > data folder (stat + prof) > lock (one run at a time) > state db > secrets > (browser commands) launch own-profile Chrome + tab > dispatch > print errors
// I/O: process Init (caller) > exit code 0-4; browser profile in <data>/prof, state in <data>/stat (data = data_loca_wind / data_loca_unix)
// ===================================================================
const std = @import("std"); const cfgz = @import("cf-conf-load.zig"); const targ = @import("ct-ctrl-args.zig"); const runz = @import("ct-ctrl-runz.zig"); const task = @import("ru-task-runn.zig"); const stat = @import("st-stat-main.zig"); const chro = @import("nt-brow-chro.zig"); const pg = @import("ru-page-snap.zig"); const pace = @import("ru-huma-pace.zig"); const lock = @import("ru-lock-main.zig"); const priv = @import("ru-safe-priv.zig"); const erro = @import("er-erro-type.zig"); const misc = @import("ct-comm-misc.zig"); const secr = @import("ut-secr-refz.zig"); const acctm = @import("ru-acct-main.zig");
const HELP = "zr: ZenRows dashboard helper that works like you, at a human pace.\n  zr secret [--acct id]       save your ZenRows email + password (2 lines on stdin; stays on this PC) | zr secret list\n  --acct <id>|all             pick one account or run every account one at a time\n  zr setup [--yes]            first run: browser, check, demo, accept the risk (--yes)\n  zr login                    open the browser, log in by hand\n  zr status [--json]          limits, quiet hours, last stop, last routine\n  zr jobs                     every job, its risk (W = ok, X = needs your OK) and limit\n  zr run <job> [flags]        one job, e.g. signup, login, key-create, fetch-run\n  zr ask \"<words>\"            e.g. \"get https://example.com as text\" | \"sign up\" | \"show usage\"\n  zr plan <routine>           list what a routine will do and what needs your OK\n  zr approve all | 1,3        approve once, up front (zr deny 2 to refuse)\n  zr flow run <routine>       run a routine by itself; it pauses only when it needs you\n  zr map                      crawl the real site (read-only), save every control, list gaps\n  zr doctor [job] [--url p]   check the buttons each job needs (read-only)\n  zr snap <path> [name]       save a redacted copy of a page for testing (read-only)\n  zr log [--json]             recent actions\n  zr pause | resume           stop or allow running jobs (resume also ends a safety rest)\n  zr unlock <key>             clear an unsure key after you checked ZenRows\n  zr report | backup | export | purge     support folder | copy of your data | JSONL export | delete old logs\nflags: --text --to --url --title --price --desc --group --photo --opt --date --time --max N --conf <file> --acct <id>|all --head (hides the window: never use it to log in) --yes\nraw mode (devs): --opt \"k=v&k=v\" sets request params, --text python|node|go|curl picks the snippet language.\nsafety: default is a dry-run preview. --read = read only. --live = do it. --live --force = also approve risky acts.\nexit: 0 ok | 1 failed | 2 usage | 3 page changed | 4 blocked (quiet hours, cap, challenge, approval, rest)";
const CF = .{ .file = "aa-conf-main.json", .cand = [_][]const u8{ "..", "../..", "." }, .dbfi = "zr-state.db", .subs = "stat", .subp = "prof", .boot = 30000, .conn = 8000, .linz = 512 };
fn confFind(allo: std.mem.Allocator, iozz: std.Io, args: targ.Args) !cfgz.Conf { if (args.conf.len > 0) return cfgz.confLoad(allo, iozz, args.conf); const dirz = std.process.executableDirPathAlloc(iozz, allo) catch "."; for (CF.cand) |rela| { const path = std.fs.path.join(allo, &.{ dirz, rela, CF.file }) catch continue; _ = std.Io.Dir.cwd().statFile(iozz, path, .{}) catch continue; return cfgz.confLoad(allo, iozz, path); } return .{}; }
fn outz(iozz: std.Io, text: []const u8) void { std.Io.File.stdout().writeStreamingAll(iozz, text) catch {}; }
fn failz(conf: cfgz.Conf, err: anyerror) u8 { const msg = erro.mesgLang(err, conf.lang_main_code); std.debug.print("error: {s} - {s}\nfix: {s}\n", .{ msg.what, msg.whyz, msg.fixz }); return erro.exitCode(err); }
const KEEP = [_][]const u8{ "jobs" };
const AllSt = struct { init: std.process.Init, args: targ.Args, conf: cfgz.Conf, book: secr.Book, root: []const u8 };
fn say(px: ?*anyopaque, msg: []const u8) void { const st: *AllSt = @ptrCast(@alignCast(px.?)); const line = std.fmt.allocPrint(st.init.arena.allocator(), "{s}\n", .{msg}) catch return; outz(st.init.io, line); }
fn runner(px: ?*anyopaque, id: []const u8) anyerror!void { const st: *AllSt = @ptrCast(@alignCast(px.?)); _ = workOne(st.init, st.args, st.conf, st.book, id, st.root) catch |err| { _ = failz(st.conf, err); return err; }; }
fn secretRun(init: std.process.Init, args: targ.Args, conf: cfgz.Conf) !u8 { const allo = init.arena.allocator(); const iozz = init.io; const home = init.environ_map.get("USERPROFILE") orelse init.environ_map.get("HOME") orelse ""; const dir = try cfgz.secrDir(allo, home, conf);
if (std.mem.eql(u8, args.subz, "list")) { const book = try secr.loadBook(allo, iozz, dir, conf.acct_maxx_coun); if (!book.filez) { outz(iozz, "no user-acct.json yet: run zr secret (email on line 1, password on line 2)\n"); return 0; } for (book.accs) |acc| { const line = try std.fmt.allocPrint(allo, "{s}{s}: user {s}, pass {s}; lang={s} caps={d}%\n", .{ acc.id, if (std.mem.eql(u8, acc.id, book.main)) " [main]" else "", if (acc.user.len > 0) "set" else "empty", if (acc.pass.len > 0) "set" else "empty", if (acc.lang.len > 0) acc.lang else "default", acc.scal }); outz(iozz, line); } return 0; }
if (std.mem.eql(u8, args.acct, "all")) return error.BadUsage; const book = try secr.loadBook(allo, iozz, dir, conf.acct_maxx_coun); const id = if (args.acct.len > 0) args.acct else book.main; var buf: [CF.linz]u8 = undefined; var rdr = std.Io.File.stdin().readerStreaming(iozz, &buf); const rdi = &rdr.interface; const user = std.mem.trim(u8, rdi.takeDelimiterExclusive('\n') catch return error.BadUsage, " \r\n"); _ = rdi.discardAll(1) catch 0; const pass = std.mem.trim(u8, rdi.takeDelimiterExclusive('\n') catch return error.BadUsage, " \r\n"); if (user.len == 0 or pass.len == 0) return error.BadUsage; try secr.saveAcc(iozz, allo, dir, conf.acct_maxx_coun, id, user, pass); const line = try std.fmt.allocPrint(allo, "saved: login for account {s} stored in the secret folder (never printed, never logged)\n", .{id}); outz(iozz, line); return 0; }
fn workOne(init: std.process.Init, args: targ.Args, conf0: cfgz.Conf, book: secr.Book, id: []const u8, root: []const u8) !u8 { const allo = init.arena.allocator(); const iozz = init.io; const user = init.environ_map.get("USERNAME") orelse init.environ_map.get("USER") orelse "";
const acc = secr.pick(book, id) orelse return error.BadUsage; var conf = acctm.applyScal(conf0, acc.scal); if (std.mem.eql(u8, acc.lang, "vi") or std.mem.eql(u8, acc.lang, "en")) conf.lang_main_code = acc.lang;
const adir = try std.fs.path.join(allo, &.{ root, "acct", id }); const sdir = try std.fs.path.join(allo, &.{ adir, CF.subs }); try std.Io.Dir.cwd().createDirPath(iozz, sdir);
const brow_cmd = runz.needBrow(args); var lck: ?lock.Lock = null; defer if (lck) |*lk| lk.release(); if (brow_cmd) lck = try lock.take(init.gpa, iozz, sdir);
const dbp = try std.fs.path.joinZ(allo, &.{ sdir, CF.dbfi }); var store = try stat.Stat.open(allo, dbp); defer store.close();
var seed = conf.rand_seed_numb; if (seed == 0) { var sb: [8]u8 = undefined; iozz.random(&sb); seed = std.mem.readInt(u64, &sb, .little); } var rng = pace.Rng.init(seed); var page: pg.Page = undefined; var brow: ?chro.Brow = null; defer if (brow) |*brw| brw.stop(); var opened = false; defer if (opened) page.closeConn();
if (brow_cmd) { const exe = (try chro.exeFind(allo, iozz, conf.brow_exec_path)) orelse return error.NoBrowser; const prof = try std.fs.path.join(allo, &.{ adir, CF.subp }); brow = chro.launch(allo, iozz, exe, prof, conf.brow_head_mode or args.head, CF.boot) catch return error.BrowFail; const wsp = try chro.pageWs(allo, iozz, brow.?.port, CF.boot); page = try pg.pageOpen(allo, iozz, brow.?.port, wsp, CF.conn); opened = true; page.arm(conf.brow_time_seco * 1000); try page.enable(allo); }
var ctx: task.Ctx = .{ .gpaz = init.gpa, .aren = allo, .iozz = iozz, .conf = conf, .store = &store, .mode = args.mode(), .page = &page, .rng = &rng, .base = conf.base_appz_main, .statd = sdir, .grant = try priv.grantFor(allo, user), .dataroot = adir, .secr_user = acc.user, .secr_pass = acc.pass, .acct = id }; return runz.dispatch(&ctx, args); }
fn work(init: std.process.Init, args: targ.Args, conf: cfgz.Conf) !u8 { const allo = init.arena.allocator(); const iozz = init.io; const home = init.environ_map.get("USERPROFILE") orelse init.environ_map.get("HOME") orelse "";
const root = cfgz.dataDir(allo, home, conf) catch return error.BadConfig; try std.Io.Dir.cwd().createDirPath(iozz, root); _ = acctm.migrate(allo, iozz, root) catch false;
const secd = cfgz.secrDir(allo, home, conf) catch ""; const book = try secr.loadBook(allo, iozz, secd, conf.acct_maxx_coun);
var keep = false; for (KEEP) |nm| { if (std.mem.eql(u8, nm, args.cmdz)) keep = true; }
if (!std.mem.eql(u8, args.acct, "all") or keep) { const id = if (args.acct.len > 0 and !std.mem.eql(u8, args.acct, "all")) args.acct else book.main; if (!secr.idOk(id)) return error.BadUsage; return workOne(init, args, conf, book, id, root); }
const brow_cmd = runz.needBrow(args); var gl: ?lock.Lock = null; defer if (gl) |*lk| lk.release(); if (brow_cmd) { const gdir = try std.fs.path.join(allo, &.{ root, "acct" }); try std.Io.Dir.cwd().createDirPath(iozz, gdir); gl = try lock.take(init.gpa, iozz, gdir); }
var ids: std.ArrayList([]const u8) = .empty; for (book.accs) |acc| try ids.append(allo, acc.id); var sb: [8]u8 = undefined; iozz.random(&sb); var rng = pace.Rng.init(std.mem.readInt(u64, &sb, .little)); var st: AllSt = .{ .init = init, .args = args, .conf = conf, .book = book, .root = root }; const now: i64 = @intCast(std.Io.Clock.real.now(iozz).toMilliseconds());
var env: acctm.Env = .{ .aren = allo, .iozz = iozz, .conf = conf, .root = root, .ids = ids.items, .now = now, .rng = &rng, .ctx = &st, .run = runner, .say = say, .browser = brow_cmd }; const res = try acctm.runAll(&env); for (res) |rs| { const line = try std.fmt.allocPrint(allo, "account {s}: {s}\n", .{ rs.id, rs.state }); outz(iozz, line); } return acctm.worst(res); }
pub fn runMain(init: std.process.Init) !u8 { const allo = init.arena.allocator(); const iozz = init.io; var iter = try init.minimal.args.iterateAllocator(allo); _ = iter.next(); var argv: std.ArrayList([]const u8) = .empty; while (iter.next()) |item| try argv.append(allo, item); const args = try targ.argsRead(argv.items); const conf = try confFind(allo, iozz, args); if (args.helz or args.cmdz.len == 0 or std.mem.eql(u8, args.cmdz, "help")) { outz(iozz, HELP ++ "\n"); return if (args.cmdz.len == 0 and !args.helz) 2 else 0; } if (std.mem.eql(u8, args.cmdz, "version")) { outz(iozz, "zr " ++ misc.VERS ++ "\n"); return 0; } if (std.mem.eql(u8, args.cmdz, "secret")) return secretRun(init, args, conf) catch |err| failz(conf, err); return work(init, args, conf) catch |err| failz(conf, err); }
